/* From Uiverse.io by mirbasit01  - Tags: 3d, card, hover, dark, code, html, css, css effect */
.__UIV_SCOPE__ .card {
  width: 330px;
  height: 370px;
  padding: 20px;
  color: white;
  background: linear-gradient(#212121, #212121) padding-box,
    linear-gradient(145deg, transparent 35%, #0a89a8, #252e31) border-box;
  border: 2px solid transparent;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transform-origin: top bottom;
  transition: all 0.8s cubic-bezier(0.23, 1, 0.32, 1);
}

.__UIV_SCOPE__ .card .main-content {
  flex: 1;
}

.__UIV_SCOPE__ .card .header span:first-child {
  font-weight: 600;
  color: #717171;
  margin-right: 4px;
}

.__UIV_SCOPE__ .card .heading {
  font-size: 24px;
  margin: 24px 0 16px;
  font-weight: 600;
}

.__UIV_SCOPE__ .card .categories {
  display: flex;
  gap: 10px;
}

.__UIV_SCOPE__ .card .categories span {
  background-color: #0a89a8;
  padding: 4px 8px;
  font-weight: 600;
  text-transform: uppercase;
  font-size: 12px;
  border-radius: 50em;
}

.__UIV_SCOPE__ .card .footer {
  font-weight: 600;
  color: #717171;
  margin-right: 4px;
}

.__UIV_SCOPE__ .card:hover {
  rotate: -6deg;
}
